/* GitHub data layer: generated from Ritweek17/capf-welfare-triage/data/generated_data.json. Derived fields are transparent welfare triage signals, never diagnoses. */

export type SourceRiskLevel = "LOW" | "MEDIUM" | "HIGH";
export type Severity = "High" | "Medium" | "Low";
export type SignalDirection = "up" | "down" | "neutral";
export type FollowUpStatus = "Pending" | "Due today" | "Logged" | "Monitor";
export type CheckInStatus = "Complete" | "Late" | "Very late";
export type DemoRole = "Welfare Officer" | "Commander" | "Personnel";
export type SignalFactor = { label: string; value: string; direction: SignalDirection };
export type RawPersonnelRecord = { personnel_id: string; name: string; battalion_id: string; role: "COMMANDER" | "WELFARE_OFFICER" | "PERSONNEL"; designation: string; age: number; service_years: number; join_date: string; current_posting: string; active: boolean; enrolled_at?: string; biometric_consent?: boolean; is_deliberate_at_risk_profile?: boolean; };
export type PersonnelRecord = RawPersonnelRecord & { id: string; initials: string; rank: string; unit: string; company: string; severity: Severity; riskScore: number; status: "Flagged" | "Steady"; signal: string; summary: string; recommendation: string; factors: SignalFactor[]; flaggedAt: string; followUpStatus: FollowUpStatus; consent: "Given" | "Not given"; checkInStatus: CheckInStatus; stabilityIndex: number; stabilityTrend: number[]; sourceNote: string; duty_hours_weekly: number; leaves_last_30_days: number; deployments_last_6_months: number; transfers_last_12_months: number; training_hours_monthly: number; mood_score: number; days_since_last_checkin: number; };
export type WelfareAlert = PersonnelRecord & { status: "Flagged" };
export type InterventionRow = { intervention_id: string; alert_id: string; personnel_id: string; welfare_officer_id: string; intervention_date: string; action_type: string; outcome: string; follow_up_date: string; notes: string; closed: boolean };

